const iconNames = {
  play: 'play', pause: 'pause', plus: 'plus', check: 'check', info: 'info',
  search: 'search', bell: 'bell', close: 'close', x: 'close',
  'chevron-down': 'chevron-down', 'chevron-left': 'chevron-left', 'chevron-right': 'chevron-right',
