    if (!video) return
    video.muted = !video.muted
    setMuted(video.muted)
    revealControls()
  }

  const changeVolume = (event) => {
    const next = Number(event.target.value)
    const video = videoRef.current
    if (!video) return
    video.volume = next
    video.muted = next === 0
    setVolume(next)
