    if (!document.fullscreenElement) wrapRef.current?.requestFullscreen?.().catch(() => {})
    else document.exitFullscreen?.()
  }

  const back = () => {
    saveProgress(videoRef.current?.currentTime || 0)
    if (window.history.length > 1) navigate(-1)
    else navigate('/browse')
