    const video = videoRef.current
    if (!video) return
    if (video.paused) {
      video.play().catch(() => setPlaying(false))
    } else {
      video.pause()
    }
    revealControls()
  }, [revealControls])

  const seekBy = (amount) => {
    const video = videoRef.current
    if (!video) return
    video.currentTime = Math.max(0, Math.min(video.duration || duration, video.currentTime + amount))
    revealControls()
  }

