      <Link className="btn btn-secondary" to="/browse">Netflix Home</Link>
    </div>
  )
}

function AppRoutes() {
  const navigate = useNavigate()
  const location = useLocation()

  useEffect(() => {
    const goLogin = () => {
      if (location.pathname !== '/login') navigate('/login', { replace: true })
    }
