.auth-fineprint { font-size: 11px; line-height: 1.5; color: #757575; margin: 16px 0 0; }
.auth-footer { position: relative; z-index: 2; min-height: 100px; background: rgba(0,0,0,.72); border-top: 1px solid rgba(255,255,255,.12); padding: 30px 8%; color: #888; font-size: 13px; }

