.profiles-page { min-height: 100vh; background: #141414; display: flex; flex-direction: column; }
.profiles-header { height: 90px; padding: 0 4%; display: flex; align-items: center; justify-content: space-between; }
.profiles-logo { border: 0; background: transparent; padding: 0; }
.profiles-logo img { width: 135px; }
.manage-button { border: 1px solid #777; background: transparent; color: #e5e5e5; padding: 9px 20px; font-size: 13px; letter-spacing: .08em; transition: border-color .18s, color .18s; }
.manage-button:hover { border-color: #fff; color: #fff; }
.profiles-main { flex: 1; display: flex; flex-direction: column; align-items: center; justify-content: center; padding: 24px 4% 70px; }
.profiles-main h1 { font-size: clamp(38px, 3.6vw, 66px); font-weight: 500; margin: 0 0 48px; letter-spacing: -.025em; }
.profiles-grid { display: flex; justify-content: center; flex-wrap: wrap; gap: clamp(18px, 2.3vw, 42px); max-width: 1200px; }
.profile-tile { width: clamp(140px, 12vw, 200px); background: transparent; border: 0; padding: 0; display: flex; flex-direction: column; align-items: center; gap: 14px; color: #808080; }
.profile-avatar-frame { width: clamp(130px, 11vw, 180px); height: clamp(130px, 11vw, 180px); position: relative; border-radius: 5px; transition: transform .18s ease, box-shadow .18s ease; display: flex; align-items: center; justify-content: center; }
.profile-avatar-frame .avatar { width: 100% !important; height: 100% !important; border-radius: 5px; }
.profile-tile:hover .profile-avatar-frame { transform: scale(1.05); box-shadow: 0 0 0 3px #fff; }
.profile-tile.selected .profile-avatar-frame { box-shadow: 0 0 0 3px #fff; }
.profile-name { color: #808080; font-size: clamp(14px, 1.1vw, 19px); transition: color .18s; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; max-width: 100%; }
.profile-tile:hover .profile-name { color: #e5e5e5; }
.profile-edit-overlay { position: absolute; inset: 0; z-index: 3; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 6px; background: rgba(0,0,0,.54); color: #fff; font-size: 12px; }
.profile-edit-overlay .icon { width: 42px !important; height: 42px !important; }
.profile-selecting { position: absolute; inset: 0; background: rgba(255,255,255,.12); }
.add-frame { border: 2px dashed #555; color: #777; background: #181818; }
.profile-tile:hover .add-frame { border-color: #ddd; color: #fff; }
.manage-hint { color: #999; margin: 28px 0 0; font-size: 13px; }
.manage-button.bottom { margin-top: 38px; }
.profiles-footer { min-height: 78px; display: flex; align-items: center; justify-content: center; color: #666; font-size: 12px; }
.profiles-footer p { margin: 0; }
.profile-editor { position: relative; width: min(540px, 94vw); background: #1d1d1d; border-radius: 6px; padding: 38px 50px 33px; margin: 55px auto; box-shadow: 0 20px 80px #000; }
.profile-editor h2 { font-size: 28px; margin: 0 0 24px; }
.profile-editor-avatar { display: flex; justify-content: center; margin: 4px 0 25px; }
.profile-editor .avatar { border-radius: 6px; }
.avatar-picker { display: flex; gap: 10px; flex-wrap: wrap; justify-content: center; margin: 0 0 20px; }
.avatar-choice { border: 2px solid transparent; border-radius: 7px; padding: 3px; background: transparent; }
.avatar-choice.active { border-color: #fff; }
.kids-checkbox { display: flex; align-items: center; gap: 9px; margin: 4px 0 22px; color: #ddd; font-size: 14px; }
.kids-checkbox input { accent-color: var(--red); width: 17px; height: 17px; }
.profile-editor-actions { display: flex; flex-wrap: wrap; gap: 10px; }
