  .landing-footer { flex-direction: column; align-items: flex-start; }
  .auth-header img { width: 112px; }
  .auth-main { padding: 10px 0 50px; }
  .auth-card { width: 100%; min-height: calc(100vh - 160px); background: #000; padding: 38px 20px; }
  .profiles-header { padding: 0 5%; height: 70px; }
  .profiles-logo img { width: 100px; }
  .profiles-main { justify-content: flex-start; padding-top: 50px; }
  .profiles-main h1 { font-size: 31px; margin-bottom: 30px; }
  .profiles-grid { gap: 18px; }
  .profile-tile { width: 130px; }
  .profile-avatar-frame { width: 120px; height: 120px; }
  .profile-name { font-size: 14px; }
  .profile-editor { padding: 32px 22px; margin: 20px auto; }
  .language-tabs { gap: 17px; overflow-x: auto; }
  .language-tabs button { white-space: nowrap; font-size: 12px; }
  .languages-hero { padding: 40px 5% 22px; }
  .languages-main { padding: 20px 5% 60px; }
  .language-select-row label { align-items: flex-start; flex-direction: column; gap: 10px; }
  .poster-grid { grid-template-columns: repeat(3, 1fr); gap: 12px 6px; }
  .simple-catalog-page { padding-top: 88px; }
  .simple-page-heading, .grid-wrap { padding-left: 5%; padding-right: 5%; }
  .search-page { padding-left: 5%; padding-right: 5%; }
  .search-page-form { gap: 9px; }
