/* Language preference rail, matching the reference's top-right selector */
.languages-hero {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 40px;
  padding: 88px 3.33% 28px;
  background: linear-gradient(180deg, #191919 0%, #141414 100%);
}
.languages-hero > h1 { font-size: clamp(29px, 2.2vw, 40px); font-weight: 500; margin: 24px 0 0; letter-spacing: -.02em; }
.language-preferences { width: min(610px, 48vw); }
.language-preferences h2 { font-size: 18px; font-weight: 500; margin: 0 0 17px; color: #d7d7d7; }
.preference-row { display: grid; grid-template-columns: 220px 1fr; align-items: center; min-height: 36px; border-bottom: 1px solid #2e2e2e; }
.preference-label { border: 0; background: none; text-align: left; padding: 6px 8px; color: #999; font-size: 14px; }
.preference-row.active .preference-label { color: #fff; font-weight: 600; }
.preference-label:hover { color: #fff; }
.preference-row select { width: 100%; background: #101010; color: #fff; border: 1px solid #4b4b4b; padding: 7px 30px 7px 10px; font-size: 12px; }
.preference-unavailable { color: #777; font-size: 12px; padding-left: 10px; }
.languages-main { padding: 25px 3.33% 80px; }
.languages-main .poster-grid { grid-template-columns: repeat(auto-fill, minmax(190px, 1fr)); }
@media (max-width: 900px) {
  .languages-hero { flex-direction: column; gap: 15px; padding-top: 82px; }
  .languages-hero > h1 { margin-top: 0; }
  .language-preferences { width: 100%; }
  .preference-row { grid-template-columns: 170px 1fr; }
}
